def minMoves(sx, sy, tx, ty):
    best = -1
    stack = [(tx, ty, 0)]
    while stack:
        x, y, steps = stack.pop()
        while True:
            if x == sx and y == sy:
                if best == -1 or steps < best:
                    best = steps
                break
            if x < sx or y < sy:
                break
            if x == y:
                if x == 0:
                    break
                stack.append((0, x, steps + 1))
                stack.append((x, 0, steps + 1))
                break
            if x < y:
                if y >= 2 * x:
                    if y % 2:
                        break
                    y //= 2
                else:
                    y -= x
            else:
                if x >= 2 * y:
                    if x % 2:
                        break
                    x //= 2
                else:
                    x -= y
            steps += 1
    return best
